const source = $input.first().json;
const alertUrl = $vars.RELIABILITY_ALERT_WEBHOOK_URL;

if (!alertUrl) {
  throw new Error('Set RELIABILITY_ALERT_WEBHOOK_URL before activating Reliability Kit — Error Intake.');
}

const execution = source.execution ?? {};
const workflow = source.workflow ?? {};
const error = execution.error ?? source.error ?? {};

return [{
  json: {
    event: 'n8n.execution.failed',
    severity: 'error',
    detectedAt: new Date().toISOString(),
    workflow: {
      id: workflow.id ?? null,
      name: workflow.name ?? null,
    },
    execution: {
      id: execution.id ?? null,
      url: execution.url ?? null,
      lastNodeExecuted: execution.lastNodeExecuted ?? null,
      mode: execution.mode ?? null,
    },
    error: {
      message: error.message ?? 'n8n execution failed without an error message',
      stack: error.stack ?? null,
    },
    runbook: 'Open the execution URL, inspect the last node, then retry only after identifying the failed dependency or input.',
  },
}];
